def human(v,key=''):
 if isinstance(v,dict):return {k:human(x,k) for k,x in v.items()}
 if isinstance(v,list):return [human(x,key) for x in v]
 if not isinstance(v,str) or key not in PROSE_KEYS:return v
 for a,b in REPLACEMENTS.items():v=v.replace(a,b)
 v=re.sub(r'(\d)(January|February|March|April|May|June|July|August|September|October|November|December)',r'\1 \2',v)
 v=re.sub(r'(January|February|March|April|May|June|July|August|September|October|November|December)(\d)',r'\1 \2',v)
 v=re.sub(r'(\d)(crore|lakh|equity|original|judicial)',r'\1 \2',v)
 v=re.sub(r'(crore|lakh)([A-Za-z])',r'\1 \2',v)
 v=re.sub(r'([,;:])(?=[A-Za-z₹])',r'\1 ',v)
 v=re.sub(r'([a-z])(?=[A-Z])',r'\1 ',v)
 v=v.replace('lakh s','lakh').replace('say2.63 lakh while§27(b) gives2,63,50,000','state ₹2.63 lakh, while §27(b) gives ₹2,63,50,000').replace('plus₹','plus ₹').replace('equals₹','equals ₹').replace('DHC§3','DHC §3').replace('receipts;2024','receipts; 2024')
 return v
