# Exact reviewed display-copy overrides. Never normalize original evidence text.
copy_path=BASE/'copy-edits.json'
if copy_path.exists():
 for filename,sections in json.loads(copy_path.read_text()).items():
  target=BASE/filename
  data=json.loads(target.read_text())
  for section,rows in sections.items():
   for row in data[section]:
    if row['id'] in rows:row.update(rows[row['id']])
  target.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
